export const NAMED_CODES_TO_UNICODE: Record<string, string> = {}

var codePoint = 0
SINGLE.split(',').forEach(function (group) {
  var i = 0
  var delta = 0
  while (group.charCodeAt(i) < 58) delta = delta * 10 + group.charCodeAt(i++) - 48
  codePoint += delta || 1
  var value = String.fromCodePoint(codePoint)
  group
    .slice(i)
    .split(' ')
    .forEach(function (name) {
      NAMED_CODES_TO_UNICODE[name] = value
    })
})
MULTI.split(',').forEach(function (group) {
  var parts = group.split(' ')
  for (var i = 1; i < parts.length; i++) NAMED_CODES_TO_UNICODE[parts[i]] = parts[0]
})

/**
 * Decode a named entity using the lookup table.
 * Returns the decoded character or undefined if not found.
 * This function enables browser builds to swap in DOM-based decoding.
 */
export function decodeEntity(name: string): string | undefined {
  return NAMED_CODES_TO_UNICODE[name] || NAMED_CODES_TO_UNICODE[name.toLowerCase()]
}
